// Deux entrées possibles : une vraie panne (le déclencheur d'erreur de n8n) ou un essai à la demande (le formulaire).
const j = $input.first().json;
const texte = v => (v === undefined || v === null) ? '' : String(v);
const ESSAIS = {
  'Service indisponible (503)': { etape: 'Appeler le service de tarifs', message: 'Service unavailable - try again later or consider setting this node to retry automatically (in the node settings)', detail: '503 Service Unavailable' },
  'Trop de requêtes (429)': { etape: "Interroger l'assistant", message: 'The service is receiving too many requests from you', detail: '429 Too Many Requests: rate limit exceeded, retry in 20s' },
  'Page introuvable (404)': { etape: 'Lire la page des tarifs', message: 'The resource you are requesting could not be found', detail: '404 Not Found: https://exemple-concurrent.fr/tarifs-2025?ref=veille&token=abc123def456ghi789jkl012' },
  'Accès refusé (401)': { etape: 'Écrire dans le CRM', message: 'Authorization failed - please check your credentials', detail: '401 Unauthorized: invalid api key tok_exemple_fictif_01 for contact jean.dupont@exemple.fr' },
  'Donnée manquante': { etape: 'Lire la réponse', message: "Cannot read properties of undefined (reading 'content')", detail: 'TypeError dans le nœud Code, ligne 12' }
};
let p, reglages = { noeud_type: '', noeud_relance: false, noeud_delai: 0 };
if (j.execution && j.workflow) {
  const e = j.execution, err = e.error || {}, noeud = err.node || {};
  // De l'étape en panne on ne garde que trois réglages, jamais ses paramètres : ils peuvent porter une adresse ou un secret.
  reglages = { noeud_type: texte(noeud.type), noeud_relance: noeud.retryOnFail === true, noeud_delai: Number(noeud.parameters && noeud.parameters.options && noeud.parameters.options.timeout) || 0 };
  p = { origine: 'panne réelle', workflow_id: texte(j.workflow.id), workflow: texte(j.workflow.name) || 'Workflow sans nom', execution_id: texte(e.id), execution_url: texte(e.url), etape: texte(e.lastNodeExecuted) || texte(err.node && err.node.name) || 'étape inconnue', message: texte(err.message) || 'Erreur sans message', detail: (texte(err.description).indexOf(texte(err.httpCode)) === 0 ? texte(err.description) : [texte(err.httpCode), texte(err.description)].filter(Boolean).join(' ')), pile: texte(err.stack), deja_relance: !!e.retryOf };
} else if (j.trigger && j.workflow) {
  const err = j.trigger.error || {}, cause = err.cause || {};
  p = { origine: 'panne réelle', workflow_id: texte(j.workflow.id), workflow: texte(j.workflow.name) || 'Workflow sans nom', execution_id: '', execution_url: '', etape: texte(err.node && err.node.name) || 'le déclencheur', message: texte(err.message) || texte(cause.message) || 'Le déclencheur a échoué', detail: texte(cause.message), pile: texte(cause.stack), deja_relance: false };
} else {
  const e = ESSAIS[texte(j.panne)] || ESSAIS['Service indisponible (503)'];
  p = Object.assign({ origine: 'essai à la demande', workflow_id: '', workflow: texte(j.workflow).trim() || "Workflow d'essai", execution_id: '', execution_url: '', pile: '', deja_relance: false }, e);
}
p.soi_meme = !!p.workflow_id && p.workflow_id === texte($workflow.id);
p.quand = new Date().toISOString();
p.max_relances = Number(j.max_relances) > 0 ? Number(j.max_relances) : 1;
p.telegram_chat_id = texte(j.telegram_chat_id);
p.adresse_n8n = texte(j.adresse_n8n).replace(/\/+$/, '');
p.rappel_minutes = Number(j.rappel_minutes) > 0 ? Number(j.rappel_minutes) : 60;
// Relance automatique : seulement pour les workflows inscrits dans Réglages. Relancer un envoi ou un paiement pourrait le faire partir deux fois.
p.relance_autorisee = !!p.workflow_id && texte(j.relance_autorisee).split(',').map(x => x.trim()).indexOf(p.workflow_id) >= 0;
// Correction sur validation : seulement pour les workflows inscrits dans Réglages. Le débogueur prépare, une personne publie d'un bouton.
p.correction_autorisee = !!p.workflow_id && texte(j.correction_autorisee).split(',').map(x => x.trim()).indexOf(p.workflow_id) >= 0;
// Correction automatique : parmi eux, les workflows où les nouvelles tentatives se publient sans attendre. Une personne peut toujours annuler.
p.correction_automatique = p.correction_autorisee && texte(j.correction_automatique).split(',').map(x => x.trim()).indexOf(p.workflow_id) >= 0;
Object.assign(p, reglages);
let importances = {}; try { importances = JSON.parse(texte(j.importance) || '{}'); } catch (e) {}
p.importance = ['critique', 'important', 'confort'].indexOf(importances[p.workflow_id]) >= 0 ? importances[p.workflow_id] : 'important';
p.cle = p.quand + '|' + (p.execution_id || Math.random().toString(36).slice(2, 10));
return [{ json: p }];

// Confidentialité : aucun secret, aucune adresse e-mail ne part vers l'IA ni vers Telegram.
const p = Object.assign({}, $input.first().json);
let n = 0;
const masquer = t => String(t || '')
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, () => { n++; return '[e-mail masqué]'; })
  .replace(/\b(Bearer|Basic)\s+[A-Za-z0-9._~+\/=-]{8,}/gi, (m, a) => { n++; return a + ' [secret masqué]'; })
  .replace(/\b(?:sk|pk|rk|xox[abp]|ghp|gho|key|tok)[-_][A-Za-z0-9_-]{10,}/gi, () => { n++; return '[clé masquée]'; })
  .replace(/([?&](?:token|key|apikey|api_key|access_token|secret|password|pwd|signature|sig)=)[^&\s"']+/gi, (m, a) => { n++; return a + '[masqué]'; })
  .replace(/\b[A-Fa-f0-9]{32,}\b/g, () => { n++; return '[identifiant masqué]'; })
  .replace(/(https?:\/\/[^\s"'?]+)\?[^\s"']*/g, (m, a) => a + '?[paramètres masqués]');
p.message = masquer(p.message).slice(0, 400);
p.detail = masquer(p.detail).slice(0, 600);
p.pile = masquer(p.pile).slice(0, 800);
p.secrets_masques = n;
return [{ json: p }];

// Qualité : la famille de la panne se décide par des règles écrites, pas par l'IA. C'est elle qui dit si une relance a un sens.
const p = Object.assign({}, $input.first().json);
const t = (p.message + ' ' + p.detail).toLowerCase();
const REGLES = [
  { famille: 'trop de requêtes', relancable: true, test: /\b429\b|too many requests|rate.?limit|quota/, cause: "Le service appelé limite le nombre de demandes : le workflow en a envoyé trop, trop vite.", correction: ["Attendre une minute, puis relancer l'exécution.", "Espacer les appels : option « Batching » du nœud, ou un nœud « Wait » entre deux appels.", "Activer « Retry On Fail » sur le nœud, avec quelques secondes d'attente."] },
  { famille: 'service indisponible', relancable: true, test: /\b50[0234]\b|bad gateway|service unavailable|not able to process your request|internal server error|gateway time|etimedout|econnreset|econnrefused|socket hang up|timed? ?out/, cause: "Le service appelé n'a pas répondu à temps. C'est en général passager.", correction: ["Relancer l'exécution.", "Activer « Retry On Fail » sur le nœud : 3 essais, 5 secondes d'attente.", "Si la panne dure, vérifier la page d'état du service."] },
  { famille: 'accès refusé', relancable: false, test: /\b40[13]\b|unauthori|forbidden|invalid api key|authentication|authorization|credential|token (is )?expired|permission/, cause: "Le service a refusé l'accès : la clé ou la connexion n'est plus valable, ou n'a pas le droit demandé.", correction: ["Ouvrir la connexion (credential) du nœud et la renouveler.", "Vérifier que la clé a bien le droit de faire cette action.", "Relancer l'exécution une fois la connexion réparée."] },
  { famille: 'adresse introuvable', relancable: false, test: /\b404\b|not found|could not be found|enotfound|getaddrinfo|no such/, cause: "L'adresse appelée n'existe plus : la page ou la ressource a été déplacée ou supprimée.", correction: ["Vérifier l'adresse dans le nœud et la mettre à jour.", "Si la liste d'adresses vient d'un fichier ou d'une table, corriger la ligne en cause.", "Régler le nœud sur « On Error : Continue » pour que les autres éléments passent quand même."] },
  { famille: 'donnée inattendue', relancable: false, test: /cannot read propert|undefined|is not iterable|unexpected token|json|is not a function|invalid syntax|\bnan\b/, cause: "Le workflow a reçu une donnée d'une forme imprévue : un champ attendu est absent ou a changé de nom.", correction: ["Ouvrir l'exécution et regarder ce que le nœud précédent a vraiment envoyé.", "Adapter le nœud au nouveau format, ou prévoir une valeur par défaut.", "Ajouter un contrôle avant : si le champ manque, sortir par une autre branche."] },
  { famille: 'réglage du nœud', relancable: false, test: /\b400\b|bad request|missing|required|parameter|must be|invalid value|not valid/, cause: "Le nœud est mal réglé pour ce cas : une valeur obligatoire manque ou n'a pas la bonne forme.", correction: ["Relire le message d'erreur : il nomme souvent le champ en cause.", "Corriger le réglage du nœud, puis tester avec le même élément."] }
];
const r = REGLES.find(x => x.test.test(t)) || { famille: 'panne non reconnue', relancable: false, cause: "La panne ne correspond à aucune règle connue.", correction: ["Ouvrir l'exécution en erreur et lire le message complet.", "Tester le nœud seul, avec le même élément."] };
const code = (t.match(/\b([45]\d\d)\b/) || [])[1] || '';
return [{ json: Object.assign(p, { famille: r.famille, relancable: r.relancable, code_http: code, cause_regle: r.cause, correction_regle: r.correction }) }];

// Mémoire : la même panne a-t-elle déjà été vue ? Une exécution ne se relance qu'une fois. Et une panne déjà signalée ne redéclenche pas d'alerte avant le délai de rappel.
const p = Object.assign({}, $('Classer la panne').first().json);
const lignes = $input.all().map(i => i.json).filter(r => r && r.workflow === p.workflow && r.etape === p.etape);
const jour = Date.now() - 24 * 3600 * 1000, heure = Date.now() - 3600 * 1000;
const recentes = lignes.filter(r => Date.parse(r.quand) > jour);
const sansEffet = recentes.filter(r => Date.parse(r.quand) > heure && /toujours là|la panne dure/.test(String(r.action))).length;
const signalee = recentes.filter(r => r.famille === p.famille && /^(à corriger|à surveiller)$/.test(String(r.etat)) && Date.now() - Date.parse(r.quand) < p.rappel_minutes * 60000).sort((a, b) => Date.parse(b.quand) - Date.parse(a.quand))[0];
const hm = t => { try { return new Date(t).toLocaleTimeString('fr-FR', { timeZone: 'Europe/Paris', hour: '2-digit', minute: '2-digit' }); } catch (e) { return new Date(t).toISOString().slice(11, 16) + ' UTC'; } };
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
p.deja_vue = recentes.length;
let action, raison;
if (p.soi_meme) { action = 'ignorer'; raison = "C'est le débogueur lui-même : il ne se répare pas tout seul."; }
else if (p.origine !== 'panne réelle') { action = 'proposer'; raison = p.relancable ? "Essai à la demande : sur une vraie panne passagère, le débogueur relance tout seul, une fois." : "Essai à la demande : une relance referait la même erreur, il faut corriger avant."; }
else if (signalee) {
  action = 'se taire'; raison = 'Même panne déjà signalée à ' + hm(signalee.quand) + ' : pas de nouvelle alerte avant ' + hm(Date.parse(signalee.quand) + p.rappel_minutes * 60000) + '.';
  Object.assign(p, { etat: 'déjà signalée', cause: signalee.cause || '', correction_texte: signalee.correction || '', verification: signalee.verification || '', confiance: signalee.confiance || '', analyse: 'mémoire', action_faite: 'déjà signalée à ' + hm(signalee.quand) + ', pas de nouvelle alerte', relance_id: '', duree_s: 0 });
}
else if (p.relancable && !p.relance_autorisee && !p.deja_relance) { action = 'proposer'; raison = "Panne passagère, mais ce workflow n'est pas inscrit pour la relance automatique : relancer pourrait refaire un envoi ou un paiement déjà parti. À relancer à la main, après vérification."; }
else if (p.relancable && !p.deja_relance && sansEffet < p.max_relances && p.execution_id) { action = 'relancer'; raison = "Panne passagère, workflow inscrit pour la relance automatique : une nouvelle tentative est sans risque."; }
else if (p.relancable) { action = 'alerter'; raison = "Déjà relancé sans succès : la panne dure, une personne doit regarder."; }
else { action = 'proposer'; raison = "Une relance referait la même erreur : il faut corriger avant."; }
p.action = action; p.raison = raison;
p.avant = ['\ud83d\udd34 <b>' + (p.origine === 'panne réelle' ? 'Panne détectée à ' : 'Essai, panne simulée à ') + hm(p.quand) + '</b>', '« ' + esc(p.workflow) + ' »', 'Étape : ' + esc(p.etape), 'Erreur : ' + esc(p.message), '', 'Diagnostic en cours, le résultat arrive dans quelques secondes.'].join('\n');
p.faits = ['Workflow : ' + p.workflow, 'Étape en panne : ' + p.etape, "Message d'erreur : " + p.message, p.detail ? 'Détail : ' + p.detail : '', 'Famille de panne, décidée par une règle : ' + p.famille, 'Déjà vue ces dernières 24 heures : ' + p.deja_vue + ' fois'].filter(Boolean).join('\n');
return [{ json: p }];

// L'IA explique, le code vérifie. Si l'IA ne répond pas ou sort du cadre, les règles écrites prennent le relais : le rapport sort toujours.
const p = Object.assign({}, $('Décider quoi faire').first().json);
const r = $input.first().json || {}, o = r.output || {};
const propre = t => String(t || '').replace(/[\u2014\u2013]/g, ',').replace(/\s+/g, ' ').trim();
let source = 'IA vérifiée par le code';
let cause = propre(o.cause), correction = Array.isArray(o.correction) ? o.correction.map(propre).filter(Boolean).slice(0, 3) : [], verification = propre(o.verification), confiance = propre(o.confiance).toLowerCase();
const ok = cause.length >= 20 && cause.length <= 420 && correction.length >= 1 && correction.every(c => c.length <= 260) && ['élevée', 'moyenne', 'faible'].indexOf(confiance) >= 0;
if (!ok) { source = 'règles écrites'; cause = p.cause_regle; correction = p.correction_regle.slice(0, 3); verification = "Relancer l'exécution : elle doit aller jusqu'au bout."; confiance = p.famille === 'panne non reconnue' ? 'faible' : 'moyenne'; }
Object.assign(p, { cause: cause, correction: correction, verification: verification, confiance: confiance, analyse: source });
return [{ json: p }];

// Ce que le débogueur a fait, dit simplement. Il relance, ou il propose. Il ne publie seul qu'un réglage, les nouvelles tentatives, sur les workflows inscrits pour cela.
const p = Object.assign({}, $('Vérifier la réponse').first().json);
const r = $input.first().json || {};
const court = t => String(t || '').replace(/\s+/g, ' ').slice(0, 140);
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let fait, etat;
if (p.action === 'ignorer') { fait = 'rien, la panne vient du débogueur lui-même'; etat = 'ignoré'; }
else if (p.action === 'relancer') {
  const err = r.error, motif = err ? court(typeof err === 'string' ? err : (err.message || err.description || '')) : '';
  if (err) { fait = /credential/i.test(motif) ? "relance impossible, la connexion à l'API de n8n n'est pas encore posée dans le nœud de relance" : 'relance impossible' + (motif ? ' (' + motif + ')' : ''); etat = 'à corriger'; }
  else if (r.status === 'success' || r.finished === true) { fait = 'relancé automatiquement, et cette fois le workflow est allé au bout' + (r.id ? ' (exécution ' + r.id + ')' : ''); etat = 'réparé'; p.relance_id = String(r.id || ''); }
  else if (r.status === 'error' || r.status === 'crashed') { fait = 'relancé automatiquement, mais la panne est toujours là'; etat = 'à surveiller'; }
  else { fait = 'relancé automatiquement' + (r.id ? ' (exécution ' + r.id + ')' : ''); etat = 'à surveiller'; }
}
else if (p.action === 'alerter') { fait = 'pas de nouvelle relance, la panne dure'; etat = 'à surveiller'; }
else { fait = 'correction proposée, rien modifié'; etat = p.origine === 'panne réelle' ? 'à corriger' : 'essai'; }
p.action_faite = fait; p.etat = etat; p.relance_id = p.relance_id || '';
p.duree_s = Math.max(1, Math.round((Date.now() - Date.parse(p.quand)) / 1000));
p.correction_texte = p.correction.join(' | ');
// Réparé tout seul, ou workflow de confort : le message part sans sonnerie. Une personne doit agir : il sonne.
p.silencieux = etat === 'réparé' || p.importance === 'confort';
// Une personne doit agir : le message porte trois boutons, relancer, mettre en pause, ne rien faire. Elle décide, un autre workflow exécute.
p.boutons = p.origine === 'panne réelle' && etat !== 'réparé' && etat !== 'ignoré' && !!p.execution_id;
// Une correction simple, choisie par une règle écrite, pour une panne passagère sur un workflow inscrit. Ici rien n'est modifié : c'est un autre workflow qui l'exécute, sur un bouton ou sur la demande du débogueur.
p.proposition = null;
if (p.origine === 'panne réelle' && p.correction_autorisee && (etat === 'réparé' || etat === 'à corriger') && p.execution_id && p.noeud_type && (p.famille === 'service indisponible' || p.famille === 'trop de requêtes')) {
  const t = (p.message + ' ' + p.detail).toLowerCase(), s = ms => Math.round(ms / 1000) + ' s';
  let geste = '', quoi = '';
  if (/timeout of|connection was aborted|econnaborted/.test(t) && /httpRequest$/.test(p.noeud_type) && p.noeud_delai > 0 && p.noeud_delai < 120000) { geste = 'd'; quoi = "allonger le délai d'attente de cette étape, de " + s(p.noeud_delai) + ' à ' + s(Math.min(p.noeud_delai * 2, 120000)) + '. Un service lent ne fera plus échouer le workflow.'; }
  else if (!p.noeud_relance) { geste = 't'; quoi = "activer les nouvelles tentatives sur cette étape, 3 essais à 5 secondes d'intervalle. Une coupure brève ne fera plus échouer le workflow."; }
  // Sans attendre : seulement les nouvelles tentatives, seulement si la relance vient de prouver que la panne était passagère, seulement sur un workflow inscrit pour cela.
  if (geste) p.proposition = { geste: geste, automatique: geste === 't' && etat === 'réparé' && p.correction_automatique === true, texte: ['🛠 <b>Correction prête pour « ' + esc(p.workflow) + ' »</b>', 'Étape : ' + esc(p.etape), 'Ce que je propose : ' + quoi, '', "Rien n'est modifié tant que vous n'appuyez pas. Après publication, un bouton permet d'annuler."].join('\n') };
}
const titre = p.origine !== 'panne réelle' ? 'ESSAI du débogueur sur « ' + esc(p.workflow) + ' »' : etat === 'réparé' ? '\ud83d\udfe2 Réparé tout seul en ' + p.duree_s + ' s : « ' + esc(p.workflow) + ' »' : etat === 'à surveiller' ? '\ud83d\udfe0 La panne dure sur « ' + esc(p.workflow) + ' »' : etat === 'ignoré' ? 'Panne du débogueur lui-même' : '\ud83d\udfe0 À corriger sur « ' + esc(p.workflow) + ' »';
const L = [];
L.push('<b>' + titre + '</b>' + (p.origine === 'panne réelle' && p.importance === 'critique' ? ' · workflow critique' : ''));
L.push('Étape : ' + esc(p.etape));
L.push('Erreur : ' + esc(p.message));
L.push('');
L.push('Cause probable : ' + esc(p.cause));
L.push('');
L.push(etat === 'réparé' ? 'Pour éviter que ça revienne :' : 'À faire :');
p.correction.filter(c => !(etat === 'réparé' && /^relancer/i.test(c))).forEach((c, k) => L.push((k + 1) + '. ' + esc(c)));
L.push('');
L.push("Ce que j'ai fait : " + esc(fait) + '.');
L.push(/impossible/.test(fait) ? "Relance à la main possible : ouvrir l'exécution, bouton « Retry »." : esc(p.raison));
if (etat === 'réparé') L.push('Aucune action nécessaire.');
if (p.deja_vue) L.push('Déjà vue ' + p.deja_vue + ' fois en 24 heures.');
if (p.secrets_masques) L.push(p.secrets_masques + (p.secrets_masques > 1 ? ' secrets masqués' : ' secret masqué') + " avant l'analyse.");
if (p.execution_url) L.push('Exécution : ' + esc(p.execution_url));
if (p.boutons) L.push('', 'À vous de décider, avec les boutons ci-dessous.');
if (p.proposition) L.push('', 'Pour que ça ne revienne pas, une correction est prête : elle arrive dans le message suivant.');
p.texte = L.join('\n').slice(0, 3500);
const ligne = (k, v) => '<tr><td style="padding:10px 14px;border-top:1px solid #E3E8EF;color:#205E8E;font-weight:600;font-size:12px;text-transform:uppercase;letter-spacing:.05em;vertical-align:top;width:170px">' + k + '</td><td style="padding:10px 14px;border-top:1px solid #E3E8EF;font-size:15px;line-height:1.5">' + v + '</td></tr>';
const pastille = (t, c) => '<span style="display:inline-block;background:' + c + ';border-radius:999px;padding:4px 12px;font-size:12.5px;font-weight:600;margin:0 6px 6px 0">' + esc(t) + '</span>';
p.html = '<div style="font-family:Poppins,Helvetica,Arial,sans-serif;color:#17202E;text-align:left;max-width:760px;margin:0 auto">'
  + '<p style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#757575;font-weight:600;margin:0 0 6px">Débogueur automatique</p>'
  + '<h2 style="font-size:24px;margin:0 0 6px">' + esc(p.workflow) + '</h2>'
  + '<p style="margin:0 0 14px">' + pastille('Famille : ' + p.famille, '#FFF0E8') + pastille(p.relancable ? 'Relance utile' : 'Relance inutile', p.relancable ? '#E4F6EE' : '#FDE7F0') + pastille('Analyse : ' + p.analyse, '#E7F1F9') + (p.secrets_masques ? pastille(p.secrets_masques + (p.secrets_masques > 1 ? ' secrets masqués' : ' secret masqué'), '#F0F0F2') : '') + '</p>'
  + '<table style="width:100%;border-collapse:collapse;background:#fff;border:1px solid #E3E8EF;border-radius:14px;overflow:hidden">'
  + ligne('Étape en panne', '<b>' + esc(p.etape) + '</b>') + ligne("Message d'erreur", '<code style="font-size:13px">' + esc(p.message) + (p.detail ? '<br>' + esc(p.detail) : '') + '</code>')
  + ligne('Cause probable', esc(p.cause)) + ligne('À faire', '<ol style="margin:0;padding-left:20px">' + p.correction.map(c => '<li>' + esc(c) + '</li>').join('') + '</ol>')
  + ligne('Pour vérifier', esc(p.verification)) + ligne('Confiance', esc(p.confiance)) + ligne("Ce que j'ai fait", '<b>' + esc(fait) + '.</b> ' + esc(p.raison))
  + '</table><p style="font-size:12.5px;color:#757575;margin:14px 0 0">Le débogueur relance une panne passagère, une seule fois, et pour le reste il propose. Il ne publie seul que les nouvelles tentatives, sur les workflows inscrits pour cela, et un bouton permet de revenir en arrière. Toute autre correction attend la validation de la personne qui maintient.</p></div>';
return [{ json: p }];
